class Traveler {
    volatile boolean asleep;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    public void countSomeSheep() {
        System.out.println("Tallying lanterns...");
    }

    public synchronized void setAsleep(boolean asleep) {
        this.asleep = asleep;
    }
}

class SleepHelper implements Runnable {
    private Traveler traveler;

    public SleepHelper(Traveler traveler) {
        this.traveler = traveler;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        traveler.setAsleep(true);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Traveler traveler = new Traveler();

        Thread thread1 = new Thread(new SleepHelper(traveler));
        thread1.start();

        traveler.tryToSleep();

        thread1.join();
    }
}

