    volatile boolean asleep;

    void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    void countSomeSheep() {
        System.out.println("Observing fireflies...");
        // simulate observing action, e.g., a short delay
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    void wakeUp() {
        asleep = false;
    }

    void fallAsleep() {
        asleep = true;
    }
}

