        Scout scout = new Scout();

        Thread observerThread = new Thread(() -> {
            scout.tryToSleep();
            System.out.println("Scout has fallen asleep.");
        });

        Thread wakeUpThread = new Thread(() -> {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println("Waking up the scout...");
            scout.wakeUp();
        });

        observerThread.start();
        wakeUpThread.start();

        observerThread.join();
        wakeUpThread.join();

        System.out.println("Main thread completed.");
    }
}

