import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, String> positions;

    public DelegatingDeviceTracker(ConcurrentHashMap<String, String> initialPositions) {
        this.positions = initialPositions;
    }

    public String getPosition(String gadgetId) {
        return positions.get(gadgetId);
    }

    public boolean updatePosition(String gadgetId, String newPosition) {
        return positions.computeIfPresent(gadgetId, (id, oldPos) -> newPosition) != null;
    }

    public ConcurrentHashMap<String, String> getLivePositions() {
        return new ConcurrentHashMap<>(positions); // Live view
    }

    public ConcurrentHashMap<String, String> getSnapshotPositions() {
        // Static snapshot
        return new ConcurrentHashMap<>(positions);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ConcurrentHashMap<String, String> initialPositions = new ConcurrentHashMap<>();
        initialPositions.put("gadget1", "position1");
        initialPositions.put("gadget2", "position2");

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Simulate concurrent updates
        Runnable updateTask = () -> {
            for (int i = 0; i < 5; i++) {
                String gadgetId = "gadget" + (i % 2 + 1);
                String newPosition = "newPosition" + i;
                if (tracker.updatePosition(gadgetId, newPosition)) {
                    System.out.println("Updated position of " + gadgetId + " to " + newPosition);
                } else {
                    System.out.println("Failed to update position of non-existent gadget");
                }
            }
        };

        executor.execute(updateTask); // Update positions
        executor.execute(updateTask); // Update positions concurrently

        Thread.sleep(1000); // Allow tasks to complete

        // Fetch and print live positions
        ConcurrentHashMap<String, String> livePositions = tracker.getLivePositions();
        System.out.println("Live Positions: " + livePositions);

        // Fetch and print snapshot positions
        ConcurrentHashMap<String, String> snapshotPositions = tracker.getSnapshotPositions();
        System.out.println("Snapshot Positions: " + snapshotPositions);

        executor.shutdown();

        // Update a non-existent gadget's position to verify the update fails
        if (!tracker.updatePosition("nonExistentGadget", "newPosition")) {
            System.out.println("Failed to update position of non-existent gadget");
        }
    }
}

