import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ReentrantLock;

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

class ParcelCount {
    private int count;

    public synchronized void setCount(int count) {
        this.count = count;
    }

    public synchronized int getCount() {
        return count;
    }

    public synchronized boolean hasSufficientItems(int quantity) {
        return count >= quantity;
    }

    public synchronized void removeItems(int quantity) {
        count -= quantity;
    }
}

class Locker {
    private ReentrantLock lock = new ReentrantLock();
    private ParcelCount parcelCount;

    public Locker(ParcelCount parcelCount) {
        this.parcelCount = parcelCount;
    }

    public boolean tryAcquireLock(long timeout, TimeUnit unit) throws InterruptedException {
        return lock.tryLock(timeout, unit);
    }

    public void releaseLock() {
        lock.unlock();
    }

    public ParcelCount getParcelCount() {
        return parcelCount;
    }
}

public class DeadlockAvoidance {
    private static long calculateFixedDelay() {
        return 100; // fixed delay component
    }

    private static long calculateRandomDelay() {
        return (long) (Math.random() * 200); // random delay component between 0 and 200 ms
    }

    public static boolean moveParcels(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException, InterruptedException {
        long startTime = System.currentTimeMillis();
        while (true) {
            if (source.tryAcquireLock(timeout, unit)) {
                try {
                    if (target.tryAcquireLock(timeout, unit)) {
                        try {
                            if (!source.getParcelCount().hasSufficientItems(quantity)) {
                                throw new NotEnoughItemsException("Not enough items in source locker");
                            }
                            source.getParcelCount().removeItems(quantity);
                            target.getParcelCount().setCount(target.getParcelCount().getCount() + quantity);
                            return true;
                        } finally {
                            target.releaseLock();
                        }
                    } else {
                        source.releaseLock();
                    }
                } catch (Exception e) {
                    source.releaseLock();
                    throw e;
                }
            }

            long elapsed = System.currentTimeMillis() - startTime;
            if (elapsed > unit.toMillis(timeout)) {
                return false; // timeout
            }

            Thread.sleep(calculateFixedDelay() + calculateRandomDelay());
        }
    }

    public static void main(String[] args) throws NotEnoughItemsException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        ParcelCount sourceParcelCount = new ParcelCount();
        sourceParcelCount.setCount(10);

        Locker sourceLocker = new Locker(sourceParcelCount);
        Locker targetLocker = new Locker(new ParcelCount());

        executor.submit(() -> {
            try {
                moveParcels(sourceLocker, targetLocker, 5, 1000, TimeUnit.MILLISECONDS);
            } catch (NotEnoughItemsException | InterruptedException e) {
                System.out.println(e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                moveParcels(targetLocker, sourceLocker, 3, 1000, TimeUnit.MILLISECONDS);
            } catch (NotEnoughItemsException | InterruptedException e) {
                System.out.println(e.getMessage());
            }
        });

        Thread.sleep(2000); // wait for threads to finish
        executor.shutdownNow();
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

class ParcelCount {
    private int count;

    public synchronized void decrement(int quantity) throws NotEnoughItemsException {
        if (count < quantity) {
            throw new NotEnoughItemsException("Not enough items in the locker");
        }
        count -= quantity;
    }

    public synchronized void increment(int quantity) {
        count += quantity;
    }

    public synchronized int getCount() {
        return count;
    }

    public ParcelCount(int initialCount) {
        this.count = initialCount;
    }
}

class Locker {
    private ReentrantLock lock;
    private ParcelCount parcelCount;

    public Locker(ParcelCount parcelCount) {
        this.parcelCount = parcelCount;
        this.lock = new ReentrantLock();
    }

    public boolean tryAcquireLock(long timeout, TimeUnit unit) throws InterruptedException {
        return lock.tryLock(timeout, unit);
    }

    public void releaseLock() {
        lock.unlock();
    }

    public ParcelCount getParcelCount() {
        return parcelCount;
    }
}

public class Main {
    private static final long FIXED_DELAY_MILLIS = 100;

    public static boolean moveParcels(Locker sourceLocker, Locker targetLocker, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException, InterruptedException {
        if (!sourceLocker.tryAcquireLock(timeout, unit)) {
            return false;
        }
        try {
            if (!targetLocker.tryAcquireLock(timeout, unit)) {
                sourceLocker.releaseLock();
                Thread.sleep(calculateFixedDelayMillis() + calculateRandomDelayMillis());
                return moveParcels(sourceLocker, targetLocker, quantity, timeout, unit);
            }
            try {
                sourceLocker.getParcelCount().decrement(quantity);
                targetLocker.getParcelCount().increment(quantity);
                return true;
            } finally {
                targetLocker.releaseLock();
            }
        } finally {
            sourceLocker.releaseLock();
        }
    }

    private static long calculateFixedDelayMillis() {
        return FIXED_DELAY_MILLIS;
    }

    private static long calculateRandomDelayMillis() {
        return (long) (Math.random() * 100);
    }

    public static void main(String[] args) throws NotEnoughItemsException, InterruptedException {
        ParcelCount sourceParcelCount = new ParcelCount(10);
        ParcelCount targetParcelCount = new ParcelCount(0);

        Locker sourceLocker = new Locker(sourceParcelCount);
        Locker targetLocker = new Locker(targetParcelCount);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try {
                System.out.println(moveParcels(sourceLocker, targetLocker, 5, 1, TimeUnit.SECONDS));
            } catch (NotEnoughItemsException | InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.submit(() -> {
            try {
                System.out.println(moveParcels(targetLocker, sourceLocker, 3, 1, TimeUnit.SECONDS));
            } catch (NotEnoughItemsException | InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();

        if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
            executor.shutdownNow();
        }

        System.out.println("Source locker count: " + sourceParcelCount.getCount());
        System.out.println("Target locker count: " + targetParcelCount.getCount());
    }
}

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

class ParcelCount {
    private int count;

    public synchronized void setCount(int count) {
        this.count = count;
    }

    public synchronized int getCount() {
        return count;
    }
}

class Locker {
    private ReentrantLock lock;
    private ParcelCount parcelCount;

    public Locker(ParcelCount parcelCount) {
        this.lock = new ReentrantLock();
        this.parcelCount = parcelCount;
    }

    public ReentrantLock getLock() {
        return lock;
    }

    public synchronized void moveItems(int quantity, Locker targetLocker) throws NotEnoughItemsException {
        if (parcelCount.getCount() < quantity) {
            throw new NotEnoughItemsException("Not enough items in the locker");
        }
        parcelCount.setCount(parcelCount.getCount() - quantity);
        targetLocker.parcelCount.setCount(targetLocker.parcelCount.getCount() + quantity);
    }

    public synchronized int getCount() {
        return parcelCount.getCount();
    }
}

public class Main {
    private static final long FIXED_DELAY = 100;
    private static final double RANDOM_DELAY_MULTIPLIER = 0.5;

    public static boolean tryAcquireLocks(Locker sourceLocker, Locker targetLocker, long timeout, java.util.concurrent.TimeUnit timeUnit) {
        long startTime = System.currentTimeMillis();
        while (System.currentTimeMillis() - startTime < timeUnit.toMillis(timeout)) {
            if (sourceLocker.getLock().tryLock()) {
                try {
                    if (targetLocker.getLock().tryLock()) {
                        return true;
                    }
                } finally {
                    sourceLocker.getLock().unlock();
                }
            }
            long delay = FIXED_DELAY + (long) (RANDOM_DELAY_MULTIPLIER * Math.random() * 1000);
            try {
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return false;
    }

    public static void moveItems(Locker sourceLocker, Locker targetLocker, int quantity, long timeout, java.util.concurrent.TimeUnit timeUnit) throws NotEnoughItemsException {
        if (!tryAcquireLocks(sourceLocker, targetLocker, timeout, timeUnit)) {
            System.out.println("Failed to acquire locks within the given timeout");
            return;
        }
        try {
            sourceLocker.moveItems(quantity, targetLocker);
        } finally {
            sourceLocker.getLock().unlock();
            targetLocker.getLock().unlock();
        }
    }

    public static void main(String[] args) {
        ParcelCount parcelCount1 = new ParcelCount();
        parcelCount1.setCount(10);

        ParcelCount parcelCount2 = new ParcelCount();
        parcelCount2.setCount(5);

        Locker locker1 = new Locker(parcelCount1);
        Locker locker2 = new Locker(parcelCount2);

        Thread thread = new Thread(() -> {
            try {
                moveItems(locker1, locker2, 3, 1000, java.util.concurrent.TimeUnit.MILLISECONDS);
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
        });
        thread.start();

        try {
            thread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Locker 1 count: " + locker1.getCount());
        System.out.println("Locker 2 count: " + locker2.getCount());
    }
}

