    }
}

class Locker {
    private ReentrantLock lock;
    private ParcelCount parcelCount;

    public Locker(ParcelCount parcelCount) {
        this.lock = new ReentrantLock();
        this.parcelCount = parcelCount;
    }

    public ReentrantLock getLock() {
        return lock;
    }

    public synchronized void moveItems(int quantity, Locker targetLocker) throws NotEnoughItemsException {
        if (parcelCount.getCount() < quantity) {
            throw new NotEnoughItemsException("Not enough items in the locker");
        }
        parcelCount.setCount(parcelCount.getCount() - quantity);
        targetLocker.parcelCount.setCount(targetLocker.parcelCount.getCount() + quantity);
    }

    public synchronized int getCount() {
        return parcelCount.getCount();
    }
}

public class Main {
    private static final long FIXED_DELAY = 100;
    private static final double RANDOM_DELAY_MULTIPLIER = 0.5;

    public static boolean tryAcquireLocks(Locker sourceLocker, Locker targetLocker, long timeout, java.util.concurrent.TimeUnit timeUnit) {
        long startTime = System.currentTimeMillis();
        while (System.currentTimeMillis() - startTime < timeUnit.toMillis(timeout)) {
            if (sourceLocker.getLock().tryLock()) {
                try {
                    if (targetLocker.getLock().tryLock()) {
                        return true;
                    }
                } finally {
                    sourceLocker.getLock().unlock();
                }
            }
            long delay = FIXED_DELAY + (long) (RANDOM_DELAY_MULTIPLIER * Math.random() * 1000);
            try {
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return false;
    }

    public static void moveItems(Locker sourceLocker, Locker targetLocker, int quantity, long timeout, java.util.concurrent.TimeUnit timeUnit) throws NotEnoughItemsException {
