public class DeadlockAvoidanceSwapper {
    private static long calculateFixedDelay(long timeout, TimeUnit unit) {
        return unit.toMillis(timeout) / 2;
    }

    private static long calculateRandomDelay(long timeout, TimeUnit unit) {
        return (long) (Math.random() * unit.toMillis(timeout));
    }

    public static boolean swap(Container origin, Container target, int numElements, long timeout, TimeUnit unit) throws InterruptedException {
        if (!origin.getElementCount().hasEnoughElements(numElements)) {
            throw new InsufficientElementsException("Origin container does not have enough elements");
        }

        long startTime = System.currentTimeMillis();

        while (true) {
            if (origin.tryAcquireLock(timeout, unit)) {
                try {
                    if (target.tryAcquireLock(timeout, unit)) {
                        try {
                            origin.getElementCount().decrement();
                            return true;
                        } finally {
                            target.releaseLock();
                        }
                    } else {
                        origin.releaseLock();
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    if (origin.isLocked()) {
                        origin.releaseLock();
                    }
                }
            }

            long elapsed = System.currentTimeMillis() - startTime;

            if (elapsed > unit.toMillis(timeout)) {
                return false;
            }

            Thread.sleep(calculateFixedDelay(timeout, unit) + calculateRandomDelay(timeout, unit));
        }
    }

