class ElementCount {
    private int count;

    public ElementCount(int count) {
        this.count = count;
    }

    public synchronized void decrement(int amount) throws InsufficientElementsException {
        if (count < amount) {
            throw new InsufficientElementsException("Insufficient elements");
        }
        count -= amount;
    }

    public synchronized int getCount() {
        return count;
    }
}

class Container {
    private final ReentrantLock lock = new ReentrantLock();
    private ElementCount elementCount;

    public Container(ElementCount elementCount) {
        this.elementCount = elementCount;
    }

    public boolean trySwap(Container target, int amount, long timeout, TimeUnit unit) throws InsufficientElementsException {
        if (!lock.tryLock()) {
            return false;
        }
        try {
            if (!target.lock.tryLock(timeout, unit)) {
                lock.unlock();
                return false;
            }
            try {
                elementCount.decrement(amount);
                target.elementCount.count += amount;
                return true;
            } finally {
                target.lock.unlock();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        } finally {
            lock.unlock();
        }
    }

    public void delayedTrySwap(Container target, int amount, long timeout, TimeUnit unit) throws InsufficientElementsException {
        long delay = calculateFixedDelay() + calculateRandomDelay();
        try {
            Thread.sleep(delay);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
        if (!trySwap(target, amount, timeout, unit)) {
            delayedTrySwap(target, amount, timeout, unit);
        }
    }

    private long calculateFixedDelay() {
        return 100;
    }

    private long calculateRandomDelay() {
        return (long) (Math.random() * 1000);
    }
}

