class InsufficientElementsException extends Exception {
    public InsufficientElementsException(String message) {
        super(message);
    }
}

class ElementCount {
    private int count;

    public ElementCount(int count) {
        this.count = count;
    }

    public synchronized void decrement() {
        count--;
    }

    public synchronized boolean hasEnoughElements(int numElements) {
        return count >= numElements;
    }
}

class Container {
    private final ReentrantLock lock;
    private final ElementCount elementCount;

    public Container(ElementCount elementCount) {
        this.lock = new ReentrantLock();
        this.elementCount = elementCount;
    }

    public boolean tryAcquireLock(long timeout, TimeUnit unit) throws InterruptedException {
        return lock.tryLock(timeout, unit);
    }

    public void releaseLock() {
        lock.unlock();
    }

    public ElementCount getElementCount() {
        return elementCount;
    }
}

public class DeadlockAvoidance {
    private static final int MAX_ATTEMPTS = 5;

    public static boolean swap(Container origin, Container target, int numElements, long timeout, TimeUnit unit) throws InsufficientElementsException, InterruptedException {
        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            if (attempt > 0) {
                calculateDelay(attempt);
                Thread.sleep(calculateFixedDelay() + calculateRandomDelay());
            }

            if (origin.tryAcquireLock(timeout, unit)) {
                try {
                    if (target.tryAcquireLock(timeout, unit)) {
                        try {
                            if (origin.getElementCount().hasEnoughElements(numElements)) {
                                origin.getElementCount().decrement();
                                return true;
                            } else {
                                throw new InsufficientElementsException("Not enough elements in the origin container");
                            }
                        } finally {
                            target.releaseLock();
                        }
                    }
                } finally {
                    origin.releaseLock();
                }
            }
        }
        return false;
    }

    private static long calculateFixedDelay() {
        return 100;
    }

    private static long calculateRandomDelay() {
        return (long) (Math.random() * 100);
    }

