import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException(String message) {
        super(message);
    }
}

class WidgetCount {
    private int count;

    public WidgetCount(int count) {
        this.count = count;
    }

    public synchronized boolean hasEnoughWidgets(int numWidgets) {
        return count >= numWidgets;
    }

    public synchronized void removeWidgets(int numWidgets) {
        count -= numWidgets;
    }

    public synchronized void addWidgets(int numWidgets) {
        count += numWidgets;
    }
}

class Bin {
    private final ReentrantLock lock = new ReentrantLock();
    private final WidgetCount widgetCount;

    public Bin(WidgetCount widgetCount) {
        this.widgetCount = widgetCount;
    }

    public boolean tryAcquireLock(long timeout, TimeUnit unit) throws InterruptedException {
        return lock.tryLock(timeout, unit);
    }

    public void releaseLock() {
        lock.unlock();
    }

    public WidgetCount getWidgetCount() {
        return widgetCount;
    }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    public static boolean moveWidgets(Bin sourceBin, Bin targetBin, int numWidgets, long timeout, TimeUnit unit) throws InterruptedException, NotEnoughWidgetsException {
        if (sourceBin == targetBin) {
            throw new IllegalArgumentException("Source and target bins must be different");
        }

        long startTime = System.currentTimeMillis();
        while (true) {
            if (acquireLocks(sourceBin, targetBin, timeout, unit)) {
                try {
                    if (!sourceBin.getWidgetCount().hasEnoughWidgets(numWidgets)) {
                        throw new NotEnoughWidgetsException("Not enough widgets in source bin");
                    }
                    sourceBin.getWidgetCount().removeWidgets(numWidgets);
                    targetBin.getWidgetCount().addWidgets(numWidgets);
                    return true;
                } finally {
                    releaseLocks(sourceBin, targetBin);
                }
            }

            long elapsed = System.currentTimeMillis() - startTime;
            if (elapsed > unit.toMillis(timeout)) {
                return false;
            }

            delayBeforeRetry(elapsed, timeout, unit);
        }
    }

    private static boolean acquireLocks(Bin sourceBin, Bin targetBin, long timeout, TimeUnit unit) throws InterruptedException {
        if (sourceBin.tryAcquireLock(0, TimeUnit.NANOSECONDS)) {
            try {
                return targetBin.tryAcquireLock(timeout, unit);
            } catch (InterruptedException e) {
                sourceBin.releaseLock();
                throw e;
            }
        }

        if (targetBin.tryAcquireLock(0, TimeUnit.NANOSECONDS)) {
            try {
                return sourceBin.tryAcquireLock(timeout, unit);
            } catch (InterruptedException e) {
                targetBin.releaseLock();
                throw e;
            }
        }

        return false;
    }

    private static void releaseLocks(Bin sourceBin, Bin targetBin) {
        if (sourceBin.lock.isLocked()) {
            sourceBin.releaseLock();
        }
        if (targetBin.lock.isLocked()) {
            targetBin.releaseLock();
        }
    }

    private static long calculateFixedDelay(long elapsed, long timeout, TimeUnit unit) {
        return Math.min(unit.toMillis(timeout) / 2, unit.toMillis(timeout) - elapsed);
    }

    private static void delayBeforeRetry(long elapsed, long timeout, TimeUnit unit) throws InterruptedException {
        long fixedDelay = calculateFixedDelay(elapsed, timeout, unit);
        long randomDelay = (long) (Math.random() * fixedDelay);
        Thread.sleep(fixedDelay + randomDelay);
    }

    public static void main(String[] args) throws Exception {
        Bin bin1 = new Bin(new WidgetCount(10));
        Bin bin2 = new Bin(new WidgetCount(5));

        Runnable task1 = () -> {
            try {
                moveWidgets(bin1, bin2, 3, 1000, TimeUnit.MILLISECONDS);
