                System.out.println("Moved widgets from bin2 to bin1");
            } catch (Exception e) {
                System.err.println("Error moving widgets: " + e.getMessage());
            }
        };

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
        if (!executor.awaitTermination(2000, TimeUnit.MILLISECONDS)) {
            System.err.println("Threads did not terminate");
        }

        System.out.println("Bin 1 widget count: " + bin1.getWidgetCount().count);
        System.out.println("Bin 2 widget count: " + bin2.getWidgetCount().count);
    }
}

