public class WidgetMover {
    private static final long FIXED_DELAY = 100;
    private static final long RANDOM_DELAY_MAX = 200;

    public static boolean moveWidgets(Bin source, Bin target, int amount, long timeout, TimeUnit unit) {
        if (source == null || target == null || amount < 0) {
            throw new IllegalArgumentException("Invalid parameters");
        }
        ReentrantLock sourceLock = source.getLock();
        ReentrantLock targetLock = target.getLock();

        while (true) {
            try {
                if (sourceLock.tryLock(timeout, unit)) {
                    try {
                        if (targetLock.tryLock(timeout, unit)) {
                            try {
                                source.moveWidgets(target, amount);
                                return true;
                            } finally {
                                targetLock.unlock();
                            }
                        }
                    } finally {
                        sourceLock.unlock();
                    }
                }
            } catch (InterruptedException | NotEnoughWidgetsException e) {
                Thread.currentThread().interrupt();
                System.out.println("Interrupted or not enough widgets");
                break;
            }

            long delay = FIXED_DELAY + (long) (Math.random() * RANDOM_DELAY_MAX);
            try {
                TimeUnit.MILLISECONDS.sleep(delay);
            } catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return false;
    }

