    private static boolean acquireLocks(Bin sourceBin, Bin targetBin, long timeout, TimeUnit unit) throws InterruptedException {
        if (sourceBin.tryAcquireLock(0, TimeUnit.NANOSECONDS)) {
            try {
                return targetBin.tryAcquireLock(timeout, unit);
            } catch (InterruptedException e) {
                sourceBin.releaseLock();
                throw e;
            }
        }

        if (targetBin.tryAcquireLock(0, TimeUnit.NANOSECONDS)) {
            try {
                return sourceBin.tryAcquireLock(timeout, unit);
            } catch (InterruptedException e) {
                targetBin.releaseLock();
                throw e;
            }
        }

        return false;
    }

    private static void releaseLocks(Bin sourceBin, Bin targetBin) {
        if (sourceBin.lock.isLocked()) {
            sourceBin.releaseLock();
        }
        if (targetBin.lock.isLocked()) {
            targetBin.releaseLock();
        }
    }

