                System.out.println("Not enough widgets in source bin");
            }
        };

        Runnable moveWidgetsTask2 = () -> {
            try {
                moveWidgets(targetBin, sourceBin, 2, 2, TimeUnit.SECONDS);
            } catch (NotEnoughWidgetsException e) {
                System.out.println("Not enough widgets in target bin");
            }
        };

        executor.execute(moveWidgetsTask1);
        executor.execute(moveWidgetsTask2);

        executor.shutdown();
    }

    public static boolean moveWidgets(Bin sourceBin, Bin targetBin, int numWidgetsToMove, long timeoutDuration, TimeUnit timeUnit) throws NotEnoughWidgetsException {
        while (true) {
            if (!sourceBin.tryAcquireLock(timeoutDuration, timeUnit)) {
                return false;
            }

            try {
                if (targetBin.tryAcquireLock(timeoutDuration, timeUnit)) {
                    try {
                        if (sourceBin.getWidgetCount().hasEnoughWidgets(numWidgetsToMove)) {
                            int newSourceCount = sourceBin.getWidgetCount().getCount() - numWidgetsToMove;
                            sourceBin.getWidgetCount().setCount(newSourceCount);

                            int newTargetCount = targetBin.getWidgetCount().getCount() + numWidgetsToMove;
                            targetBin.getWidgetCount().setCount(newTargetCount);

                            System.out.println("Moved " + numWidgetsToMove + " widgets from source bin to target bin");

                            return true;
                        } else {
                            throw new NotEnoughWidgetsException("Not enough widgets in source bin");
                        }
                    } finally {
                        targetBin.releaseLock();
                    }
                }

                pauseBeforeRetryingAcquisition();
            } finally {
                sourceBin.releaseLock();
            }
        }
    }

    private static long calculateFixedDelayComponent() {
        return FIXED_DELAY_COMPONENT;
    }

    private static long calculateRandomDelayComponent() {
        double randomMultiplier = Math.random() * RANDOM_DELAY_COMPONENT_MULTIPLIER;
        return (long) (randomMultiplier * 1000); // Convert to milliseconds
    }

    private static void pauseBeforeRetryingAcquisition() throws InterruptedException {
        long delay = calculateFixedDelayComponent() + calculateRandomDelayComponent();
        Thread.sleep(delay);
    }
}
