import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException(String message) {
        super(message);
    }
}

class WidgetCount {
    private int count;

    public WidgetCount(int count) {
        this.count = count;
    }

    public synchronized void decrement(int amount) {
        if (count < amount) {
            throw new NotEnoughWidgetsException("Not enough widgets");
        }
        count -= amount;
    }

    public synchronized boolean hasEnough(int amount) {
        return count >= amount;
    }

    public synchronized int getCount() {
        return count;
    }
}

class Bin {
    private WidgetCount widgetCount;
    private ReentrantLock lock;

    public Bin(WidgetCount widgetCount) {
        this.widgetCount = widgetCount;
        this.lock = new ReentrantLock();
    }

    public ReentrantLock getLock() {
        return lock;
    }

    public synchronized void moveWidgets(Bin target, int amount) throws NotEnoughWidgetsException {
        if (!widgetCount.hasEnough(amount)) {
            throw new NotEnoughWidgetsException("Not enough widgets");
        }
        widgetCount.decrement(amount);
        System.out.println("Moved " + amount + " widgets from bin to bin. Remaining: " + widgetCount.getCount());
    }
}

public class WidgetMover {
    private static final long FIXED_DELAY = 100;
    private static final long RANDOM_DELAY_MAX = 200;

    public static boolean moveWidgets(Bin source, Bin target, int amount, long timeout, TimeUnit unit) {
        if (source == null || target == null || amount < 0) {
            throw new IllegalArgumentException("Invalid parameters");
        }
        ReentrantLock sourceLock = source.getLock();
        ReentrantLock targetLock = target.getLock();

        while (true) {
            try {
                if (sourceLock.tryLock(timeout, unit)) {
                    try {
                        if (targetLock.tryLock(timeout, unit)) {
                            try {
                                source.moveWidgets(target, amount);
                                return true;
                            } finally {
                                targetLock.unlock();
                            }
                        }
                    } finally {
                        sourceLock.unlock();
                    }
                }
            } catch (InterruptedException | NotEnoughWidgetsException e) {
                Thread.currentThread().interrupt();
                System.out.println("Interrupted or not enough widgets");
                break;
            }

            long delay = FIXED_DELAY + (long) (Math.random() * RANDOM_DELAY_MAX);
            try {
                TimeUnit.MILLISECONDS.sleep(delay);
            } catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return false;
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        WidgetCount widgetCount1 = new WidgetCount(10);
        Bin bin1 = new Bin(widgetCount1);
        WidgetCount widgetCount2 = new WidgetCount(5);
        Bin bin2 = new Bin(widgetCount2);

        Runnable task1 = () -> {
            try {
                moveWidgets(bin1, bin2, 3, 1, TimeUnit.SECONDS);
            } catch (Exception e) {
                System.out.println("Error in task1: " + e.getMessage());
            }
        };

        Runnable task2 = () -> {
            try {
                moveWidgets(bin2, bin1, 2, 1, TimeUnit.SECONDS);
            } catch (Exception e) {
                System.out.println("Error in task2: " + e.getMessage());
            }
        };

        executor.submit(task1);
        executor.submit(task2);

        executor.shutdown();
        if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
            System.out.println("Timeout occurred");
        }

        System.out.println("Final widget count in bin1: " + bin1.widgetCount.getCount());
        System.out.println("Final widget count in bin2: " + bin2.widgetCount.getCount());
    }
}
