import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Glyph {
    int spark;
    int glimmer;

    public Glyph(int spark, int glimmer) {
        this.spark = spark;
        this.glimmer = glimmer;
    }

    @Override
    public String toString() {
        return "(" + spark + ", " + glimmer + ")";
    }
}

class MysticBeastTracker {
    private ConcurrentHashMap<String, Glyph> perches;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        this.perches = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return java.util.Collections.unmodifiableMap(perches);
    }

    public Glyph getPerch(String sigil) {
        return perches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        if (!perches.containsKey(sigil)) {
            throw new IllegalArgumentException("Beast does not exist");
        }
        perches.put(sigil, new Glyph(spark, glimmer));
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return java.util.Collections.unmodifiableMap(new ConcurrentHashMap<>(perches));
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        MysticBeastTracker tracker = new MysticBeastTracker(java.util.Map.of(
                "sigil1", new Glyph(1, 2),
                "sigil2", new Glyph(3, 4)
        ));

        Runnable task1 = () -> {
            System.out.println("Task 1: Get perches");
            System.out.println(tracker.getPerches());
        };

        Runnable task2 = () -> {
            System.out.println("Task 2: Get perch of sigil1");
            System.out.println(tracker.getPerch("sigil1"));
        };

        Runnable task3 = () -> {
            System.out.println("Task 3: Set new perch for sigil1");
            tracker.setPerch("sigil1", 5, 6);
            System.out.println(tracker.getPerch("sigil1"));
        };

        Runnable task4 = () -> {
            System.out.println("Task 4: Get perches as static");
            System.out.println(tracker.getPerchesAsStatic());
        };

        executor.execute(task1);
        executor.execute(task2);
        executor.execute(task3);
        executor.execute(task4);

        Thread thread5 = new Thread(() -> {
            try {
                Thread.sleep(1000);
                System.out.println("Task 5: Get perches after all tasks");
                System.out.println(tracker.getPerches());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        thread5.start();

        executor.shutdown();
        thread5.join();
    }
}
