class SpellCaster {
    private ExecutorService executor;

    public SpellCaster(int threads) {
        this.executor = Executors.newFixedThreadPool(threads);
    }

    public void sequentialProcess(List<Charm> charms) {
        for (Charm charm : charms) {
            System.out.println(charm.compute());
        }
    }

    public List<Integer> parallelProcess(List<Charm> charms) throws InterruptedException {
        List<Integer> results = new ArrayList<>();
        for (Charm charm : charms) {
            final Charm c = charm;
            executor.submit(() -> results.add(c.compute()));
        }
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(10);
        }
        return results;
    }

    public void recursiveSequentialProcess(RuneNode node, List<Integer> results) {
        results.add(node.compute());
        for (RuneNode child : node.getChildren()) {
            recursiveSequentialProcess(child, results);
        }
    }

    public List<Integer> recursiveParallelProcess(RuneNode node) throws InterruptedException {
        List<Integer> results = new ArrayList<>();
        if (node.getChildren().isEmpty()) {
            results.add(node.compute());
        } else {
            for (RuneNode child : node.getChildren()) {
                final RuneNode c = child;
                executor.submit(() -> {
                    recursiveParallelProcessHelper(c, results);
                });
            }
            executor.shutdown();
            while (!executor.isTerminated()) {
                Thread.sleep(10);
            }
        }
        return results;
    }

    private void recursiveParallelProcessHelper(RuneNode node, List<Integer> results) {
        if (node.getChildren().isEmpty()) {
            results.add(node.compute());
        } else {
            results.add(node.compute());
            for (RuneNode child : node.getChildren()) {
                recursiveParallelProcessHelper(child, results);
            }
        }
    }
}

