class Hoard {
    private String name;
    private int gems;

    public Hoard(String name, int gems) {
        this.name = name;
        this.gems = gems;
    }

    public synchronized void withdraw(int amount) {
        if (amount > gems) {
            throw new InsufficientGemsException("Insufficient gems in " + name);
        }
        gems -= amount;
    }

    public synchronized void deposit(int amount) {
        gems += amount;
    }

    public int getGems() {
        return gems;
    }

    public String getName() {
        return name;
    }

    @Override
    public int hashCode() {
        return name.hashCode();
    }
}

class GemAmount implements Runnable {
    private Hoard source;
    private Hoard target;
    private int amount;

    public GemAmount(Hoard source, Hoard target, int amount) {
        this.source = source;
        this.target = target;
        this.amount = amount;
    }

    @Override
    public void run() {
        transferGems(source, target, amount);
    }
}

class InsufficientGemsException extends RuntimeException {
    public InsufficientGemsException(String message) {
        super(message);
    }
}

public class GemTransfer {
    private static final Object tieBreakerLock = new Object();

    public static void transferGems(Hoard source, Hoard target, int amount) {
        int sourceHashCode = System.identityHashCode(source);
        int targetHashCode = System.identityHashCode(target);

        if (sourceHashCode == targetHashCode) {
            synchronized (tieBreakerLock) {
                performTransfer(source, target, amount);
            }
        } else {
            Hoard firstHoard;
            Hoard secondHoard;

            if (sourceHashCode < targetHashCode) {
                firstHoard = source;
                secondHoard = target;
            } else {
                firstHoard = target;
                secondHoard = source;
            }

            synchronized (firstHoard) {
                synchronized (secondHoard) {
                    performTransfer(source, target, amount);
                }
            }
        }
