            } else {
                Object tieBreakingLock = new Object();
                synchronized (tieBreakingLock) {
                    synchronized (source) {
                        synchronized (destination) {
                            performTransfer();
                        }
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Error during transfer: " + e.getMessage());
