class MagicalOrbVault {
    private final Orb[] orbs;
    private int size;
    private final java.util.concurrent.Semaphore availableOrbs;
    private final java.util.concurrent.Semaphore remainingSlots;

    public MagicalOrbVault(int capacity) {
        this.orbs = new Orb[capacity];
        this.size = 0;
        this.availableOrbs = new java.util.concurrent.Semaphore(0);
        this.remainingSlots = new java.util.concurrent.Semaphore(capacity);
    }

    public void put(Orb orb) throws InterruptedException {
        remainingSlots.acquire();
        synchronized (orbs) {
            orbs[size] = orb;
            size++;
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        synchronized (orbs) {
            Orb orb = orbs[size - 1];
            size--;
            return orb;
        } finally {
            remainingSlots.release();
        }
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == orbs.length;
    }
}

