public class SimulatedCAS {
private int value;

public synchronized int get() {
return value;
}

public synchronized int compareAndSwap(int expectedValue, int newValue) {
int oldValue = value;
if (oldValue == expectedValue) {
value = newValue;
}
return oldValue;
}

public synchronized boolean compareAndSet(int expectedValue, int newValue) {
return expectedValue == compareAndSwap(expectedValue, newValue);
}

public static void main(String[] args) throws InterruptedException {
final SimulatedCAS cas = new SimulatedCAS();

// Reduce number of threads and iterations for faster JPF analysis
int threadCount = 2;
int iterationsPerThread = 3;

Thread[] threads = new Thread[threadCount];
for (int i = 0; i < threadCount; i++) {
final int threadId = i;
threads[i] = new Thread(new Runnable() {
public void run() {
for (int j = 0; j < iterationsPerThread; j++) {
int expected;
do {
expected = cas.get();
} while (!cas.compareAndSet(expected, expected + 1));
System.out.println(Thread.currentThread().getName() + " incremented to: " + cas.get());
}
}
}, "Worker-" + threadId);
threads[i].start();
}

for (Thread t : threads) {
t.join();
}

System.out.println("Final value: " + cas.get());
System.out.println("Expected value: " + (threadCount * iterationsPerThread));
}
