    int shimmerY;

    public MutableOrb(int shimmerX, int shimmerY) {
        this.shimmerX = shimmerX;
        this.shimmerY = shimmerY;
    }

    public MutableOrb(MutableOrb orb) {
        this.shimmerX = orb.shimmerX;
        this.shimmerY = orb.shimmerY;
    }
}

class ChronomanticDragonTracker {
    private Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return deepClone(constellation);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        if (constellation.containsKey(sigil)) {
            return new MutableOrb(constellation.get(sigil));
        } else {
            return null;
        }
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found");
        }
        constellation.put(sigil, new MutableOrb(shimmerX, shimmerY));
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> map) {
        Map<String, MutableOrb> clone = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : map.entrySet()) {
