import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class DollarAmount {
    private double amount;

    public DollarAmount(double amount) {
        this.amount = amount;
    }

    public double getAmount() {
        return amount;
    }
}

class Account {
    private ReentrantLock lock;
    private DollarAmount balance;

    public Account(DollarAmount initialBalance) {
        this.lock = new ReentrantLock();
        this.balance = initialBalance;
    }

    public boolean withdraw(DollarAmount amount) {
        if (balance.getAmount() >= amount.getAmount()) {
            balance = new DollarAmount(balance.getAmount() - amount.getAmount());
            return true;
        }
        return false;
    }

    public void deposit(DollarAmount amount) {
        balance = new DollarAmount(balance.getAmount() + amount.getAmount());
    }

    public ReentrantLock getLock() {
        return lock;
    }

    public DollarAmount getBalance() {
        return balance;
    }
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

public class BankTransfer {
    private static final int MAX_ATTEMPTS = 2;

    public static boolean transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit)
            throws InsufficientFundsException {
        long timeoutMs = unit.toMillis(timeout);
        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            if (acquireLocks(source.getLock(), destination.getLock(), timeoutMs)) {
                try {
                    if (source.getBalance().getAmount() >= amount.getAmount()) {
                        source.withdraw(amount);
                        destination.deposit(amount);
                        return true;
                    } else {
                        throw new InsufficientFundsException("Insufficient funds in the source account");
                    }
                } finally {
                    source.getLock().unlock();
                    destination.getLock().unlock();
                }
            } else {
                delayBeforeRetry(attempt);
            }
        }
        return false;
    }

    private static boolean acquireLocks(ReentrantLock lock1, ReentrantLock lock2, long timeoutMs) {
        if (lock1.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) {
            try {
                if (lock2.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) {
                    return true;
                } else {
                    lock1.unlock();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return false;
    }

    private static void delayBeforeRetry(int attempt) {
        long fixedDelay = 100; // ms
        long randomDelay = (long) (Math.random() * 200); // ms
        try {
            TimeUnit.MILLISECONDS.sleep(fixedDelay + randomDelay);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) throws InsufficientFundsException {
        Account account1 = new Account(new DollarAmount(1000));
        Account account2 = new Account(new DollarAmount(500));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> {
            try {
                transfer(account1, account2, new DollarAmount(200), 1, TimeUnit.SECONDS);
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        });
        executor.submit(() -> {
            try {
                transfer(account2, account1, new DollarAmount(100), 1, TimeUnit.SECONDS);
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        });

        executor.shutdown();
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class DollarAmount {
    private double amount;

    public DollarAmount(double amount) {
        this.amount = amount;
    }

    public double getAmount() {
        return amount;
    }
}

class Account {
    private String id;
    private DollarAmount balance;
    private ReentrantLock lock;

    public Account(String id, DollarAmount balance) {
        this.id = id;
        this.balance = balance;
        this.lock = new ReentrantLock();
    }

    public String getId() {
        return id;
    }

    public DollarAmount getBalance() {
        return balance;
    }

    public void setBalance(DollarAmount balance) {
        this.balance = balance;
    }

    public ReentrantLock getLock() {
        return lock;
    }
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

public class Main {
    private static final int MAX_ATTEMPTS = 3;

    public static boolean transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit) throws InterruptedException, InsufficientFundsException {
        ReentrantLock sourceLock = source.getLock();
        ReentrantLock destLock = destination.getLock();

        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            if (sourceLock.tryLock(timeout, unit)) {
                try {
                    if (destLock.tryLock(timeout, unit)) {
                        try {
                            if (source.getBalance().getAmount() >= amount.getAmount()) {
                                source.setBalance(new DollarAmount(source.getBalance().getAmount() - amount.getAmount()));
                                destination.setBalance(new DollarAmount(destination.getBalance().getAmount() + amount.getAmount()));
                                return true;
                            } else {
                                throw new InsufficientFundsException("Insufficient funds in source account");
                            }
                        } finally {
                            destLock.unlock();
                        }
                    }
                } finally {
                    sourceLock.unlock();
                }

                if (attempt < MAX_ATTEMPTS - 1) {
                    calculateFixedDelay(attempt);
                    calculateRandomBackoff(attempt);
                }
            } else {
                return false;
            }
        }

        return false;
    }

    private static void calculateFixedDelay(int attempt) throws InterruptedException {
        Thread.sleep(100 * (attempt + 1));
    }

    private static void calculateRandomBackoff(int attempt) throws InterruptedException {
        int random = (int) (Math.random() * 2);
        Thread.sleep(random * 100);
    }

    public static void main(String[] args) throws InterruptedException, InsufficientFundsException {
        Account account1 = new Account("Account1", new DollarAmount(1000));
        Account account2 = new Account("Account2", new DollarAmount(500));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> {
            try {
                System.out.println(transfer(account1, account2, new DollarAmount(200), 1, TimeUnit.SECONDS));
            } catch (InterruptedException | InsufficientFundsException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.submit(() -> {
            try {
                System.out.println(transfer(account2, account1, new DollarAmount(100), 1, TimeUnit.SECONDS));
            } catch (InterruptedException | InsufficientFundsException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class DollarAmount {
    private double amount;

    public DollarAmount(double amount) {
        this.amount = amount;
    }

    public double getAmount() {
        return amount;
    }
}

class Account {
    private ReentrantLock lock;
    private DollarAmount balance;

    public Account(DollarAmount initialBalance) {
        this.lock = new ReentrantLock();
        this.balance = initialBalance;
    }

    public boolean tryTransfer(Account dest, DollarAmount amount, long timeout, TimeUnit unit) throws InsufficientFundsException {
        if (!lock.tryLock()) return false;
        try {
            if (!dest.lock.tryLock(timeout, unit)) {
                lock.unlock();
                return false;
            }
            try {
                if (balance.getAmount() < amount.getAmount()) throw new InsufficientFundsException("Insufficient funds");
                balance = new DollarAmount(balance.getAmount() - amount.getAmount());
                dest.balance = new DollarAmount(dest.balance.getAmount() + amount.getAmount());
                return true;
            } finally {
                dest.lock.unlock();
            }
        } finally {
            lock.unlock();
        }
    }

    public void backoff() throws InterruptedException {
        Thread.sleep(calculateFixedDelay() + calculateRandomDelay());
    }

    private long calculateFixedDelay() {
        return 100;
    }

    private long calculateRandomDelay() {
        return (long) (Math.random() * 200);
    }
}

public class DeadlockAvoidance {
    public static void main(String[] args) throws InterruptedException, InsufficientFundsException {
        Account account1 = new Account(new DollarAmount(1000));
        Account account2 = new Account(new DollarAmount(500));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> {
            try {
                if (!account1.tryTransfer(account2, new DollarAmount(200), 1, TimeUnit.SECONDS)) {
                    System.out.println("Failed to transfer from account1 to account2");
                    account1.backoff();
                    if (!account1.tryTransfer(account2, new DollarAmount(200), 1, TimeUnit.SECONDS)) {
                        System.out.println("Still failed to transfer from account1 to account2");
                    }
                } else {
                    System.out.println("Transferred from account1 to account2 successfully");
                }
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.submit(() -> {
            try {
                if (!account2.tryTransfer(account1, new DollarAmount(100), 1, TimeUnit.SECONDS)) {
                    System.out.println("Failed to transfer from account2 to account1");
                    account2.backoff();
                    if (!account2.tryTransfer(account1, new DollarAmount(100), 1, TimeUnit.SECONDS)) {
                        System.out.println("Still failed to transfer from account2 to account1");
                    }
                } else {
                    System.out.println("Transferred from account2 to account1 successfully");
                }
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

