    public synchronized void put(E x) throws InterruptedException {
        while (size == capacity) {
            wait();
        }
        buffer[putIndex] = x;
        putIndex = (putIndex + 1) % capacity;
        size++;
        notifyAll();
    }

    public synchronized E take() throws InterruptedException {
