import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static final Logger LOGGER = Logger.getLogger(MyAppThread.class.getName());
    private static AtomicInteger threadCounter = new AtomicInteger(0);
    private static volatile boolean debugLifecycle = false;
    private static AtomicInteger created = new AtomicInteger(0);
    private static AtomicInteger alive = new AtomicInteger(0);

    public MyAppThread(Runnable target) {
        super(target, DEFAULT_NAME + "-" + threadCounter.incrementAndGet());
        setUncaughtExceptionHandler((thread, exception) -> LOGGER.severe("Thread " + thread.getName() + " threw an uncaught exception: " + exception.getMessage()));
    }

    @Override
    public void run() {
        created.incrementAndGet();
        alive.incrementAndGet();
        if (debugLifecycle) {
            System.out.println("Thread " + Thread.currentThread().getName() + " started");
        }
        try {
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                System.out.println("Thread " + Thread.currentThread().getName() + " finished");
            }
        }
    }

    public static int getCreatedThreads() {
        return created.get();
    }

    public static int getAliveThreads() {
        return alive.get();
    }

    public static void setDebug(boolean debug) {
        debugLifecycle = debug;
    }

    public static void main(String[] args) {
