class DynamicOrderDeadlock {
    static class Account {
        private double balance;

        public Account(double balance) {
            this.balance = balance;
        }

        public synchronized void withdraw(DollarAmount amount) throws InsufficientFundsException {
            if (balance < amount.getAmount()) {
                throw new InsufficientFundsException();
            }
            balance -= amount.getAmount();
        }

        public synchronized void deposit(DollarAmount amount) {
            balance += amount.getAmount();
        }

        public double getBalance() {
            return balance;
        }
    }

    static class DollarAmount {
        private double amount;

        public DollarAmount(double amount) {
            this.amount = amount;
        }

        public double getAmount() {
            return amount;
        }
    }

    static class InsufficientFundsException extends Exception {}

    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        Object firstLock, secondLock;

        if (from.hashCode() < to.hashCode()) {
            firstLock = from;
            secondLock = to;
        } else {
            firstLock = to;
            secondLock = from;
        }

        synchronized (firstLock) {
            synchronized (secondLock) {
                from.withdraw(amount);
                to.deposit(amount);
            }
        }
    }

    public static class DemonstrateDeadlock {
        public static void main(String[] args) {
            Account[] accounts = new Account[2];
            for (int i = 0; i < accounts.length; i++) {
                accounts[i] = new Account(100.0);
            }

            Thread thread1 = new TransferThread(accounts, 2);
            Thread thread2 = new TransferThread(accounts, 2);

            thread1.start();
            thread2.start();

            try {
                thread1.join();
                thread2.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        static class TransferThread extends Thread {
            private Account[] accounts;
            private int iterations;

            public TransferThread(Account[] accounts, int iterations) {
                this.accounts = accounts;
                this.iterations = iterations;
            }

            @Override
            public void run() {
                Random random = new Random();
                for (int i = 0; i < iterations; i++) {
                    Account fromAccount = accounts[random.nextInt(accounts.length)];
                    Account toAccount = accounts[random.nextInt(accounts.length)];

                    if (fromAccount == toAccount) {
                        continue;
                    }

                    DollarAmount amount = new DollarAmount(random.nextDouble() * 10.0);
                    try {
                        DynamicOrderDeadlock.transferMoney(fromAccount, toAccount, amount);
                    } catch (InsufficientFundsException e) {
                        // Ignore exception
                    }
                }
            }
        }
    }
