class DynamicOrderDeadlock {
    static class TransferThread extends Thread {
        private final Account[] accounts;

        public TransferThread(Account[] accounts) {
            this.accounts = accounts;
        }

        @Override
        public void run() {
            Random random = new Random();
            for (int i = 0; i < 2; i++) {
                int fromIndex = random.nextInt(accounts.length);
                int toIndex = random.nextInt(accounts.length);
                Account fromAccount = accounts[fromIndex];
                Account toAccount = accounts[toIndex];
                DollarAmount amount = new DollarAmount(random.nextInt(2) + 1);
                try {
                    transferMoney(fromAccount, toAccount, amount);
                } catch (InsufficientFundsException e) {}
            }
        }

        private void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
            Object lock1 = from.lock;
            Object lock2 = to.lock;
            if (lock1.hashCode() < lock2.hashCode()) {
                synchronized (lock1) {
                    synchronized (lock2) {
                        from.withdraw(amount);
                        to.deposit(amount);
                    }
                }
            } else {
                synchronized (lock2) {
                    synchronized (lock1) {
                        from.withdraw(amount);
                        to.deposit(amount);
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
