class DynamicOrderDeadlock {
    static class Account {
        private int balance;

        public Account(int balance) {
            this.balance = balance;
        }

        public synchronized void withdraw(int amount) throws InsufficientFundsException {
            if (balance < amount) {
                throw new InsufficientFundsException();
            }
            balance -= amount;
        }

        public synchronized void deposit(int amount) {
            balance += amount;
        }

        public int getBalance() {
            return balance;
        }
    }

    static class DollarAmount {
        private int amount;

        public DollarAmount(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class InsufficientFundsException extends Exception {}

    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        Account firstLock = from;
        Account secondLock = to;

        if (System.identityHashCode(from) > System.identityHashCode(to)) {
            firstLock = to;
            secondLock = from;
        }

        synchronized (firstLock) {
            synchronized (secondLock) {
