class Cache {
    private final java.math.BigInteger number;
    private final java.math.BigInteger[] factors;

    public Cache(java.math.BigInteger number, java.math.BigInteger[] factors) {
        this.number = number;
        this.factors = factors.clone();
    }

    public java.math.BigInteger[] getFactors(java.math.BigInteger inputNumber) {
        if (inputNumber.equals(number)) {
            return factors.clone();
        }
        return null;
    }
}

class FactorCalculator implements Runnable {
    private final Cache cache;
    private final java.math.BigInteger number;

    public FactorCalculator(Cache cache, java.math.BigInteger number) {
        this.cache = cache;
        this.number = number;
    }

    @Override
    public void run() {
        java.math.BigInteger[] factors = calculateFactors(number);
        if (factors != null) {
            System.out.println("Calculated factors for " + number + ": " + java.util.Arrays.toString(factors));
            Cache newCache = new Cache(number, factors);
            java.math.BigInteger[] cachedFactors = newCache.getFactors(number);
            if (cachedFactors != null) {
                System.out.println("Cached factors for " + number + ": " + java.util.Arrays.toString(cachedFactors));
            }
        }
    }

    private java.math.BigInteger[] calculateFactors(java.math.BigInteger number) {
        java.util.List<java.math.BigInteger> factors = new java.util.ArrayList<>();
        for (int i = 1; i <= 2; i++) {
            if (number.mod(java.math.BigInteger.valueOf(i)).equals(java.math.BigInteger.ZERO)) {
                factors.add(java.math.BigInteger.valueOf(i));
            }
        }
        return factors.isEmpty() ? null : factors.toArray(new java.math.BigInteger[0]);
    }
}

