import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

interface Element {
    void process();
}

class Node implements Element {
    List<Node> children = new ArrayList<>();
    String value;

    public Node(String value) {
        this.value = value;
    }

    @Override
    public void process() {
        System.out.println("Processing node: " + value);
    }

    public void addChild(Node child) {
        children.add(child);
    }

    public List<Node> getChildren() {
        return children;
    }
}

class SequentialProcessor {
    public static void processElements(List<Element> elements) {
        for (Element element : elements) {
            element.process();
        }
    }

    public static void processTree(Node node) {
        node.process();
        for (Node child : node.getChildren()) {
            processTree(child);
        }
    }
}

class ParallelProcessor {
    private ExecutorService executor = Executors.newFixedThreadPool(2);

    public List<String> processElements(List<Element> elements) throws InterruptedException {
        List<String> results = new ArrayList<>();
        for (Element element : elements) {
            int index = elements.indexOf(element);
            final Element elem = element;
            final int idx = index;
            executor.submit(() -> {
                elem.process();
                synchronized (results) {
                    results.add("Processed element " + idx);
                }
            });
        }
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(10);
        }
        return results;
    }

    public List<String> processTree(Node node) throws InterruptedException {
        List<String> results = new ArrayList<>();
        processNode(node, results);
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(10);
        }
        return results;
    }

    private void processNode(final Node node, final List<String> results) {
        int index = node.getChildren().indexOf(node);
        if (index == -1) index = 0;
        final Node n = node;
        executor.submit(() -> {
            n.process();
            synchronized (results) {
                results.add("Processed node " + n.value);
            }
            for (Node child : n.getChildren()) {
                processNode(child, results);
            }
        });
    }

    public void shutdown() {
        executor.shutdownNow();
