import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

interface Element {
    int compute();
}

class Node implements Element {
    private List<Node> children = new ArrayList<>();
    private int value;

    public Node(int value) {
        this.value = value;
    }

    public void addChild(Node node) {
        children.add(node);
    }

    @Override
    public int compute() {
        return value;
    }

    public List<Node> getChildren() {
        return children;
    }
}

class Processor {
    private ExecutorService executor;

    public Processor(ExecutorService executor) {
        this.executor = executor;
    }

    public void processSequentially(List<Element> elements, List<Integer> results) {
        for (Element element : elements) {
            results.add(element.compute());
        }
    }

    public void processInParallel(List<Element> elements, List<Integer> results) throws InterruptedException {
        List<Runnable> tasks = new ArrayList<>();
        for (final Element element : elements) {
            tasks.add(() -> results.add(element.compute()));
        }
        for (Runnable task : tasks) {
            executor.submit(task);
        }
        while (!tasks.isEmpty()) {
            Thread.sleep(10);
        }
    }

    public void processTreeSequentially(Node node, List<Integer> results) {
        results.add(node.compute());
        for (Node child : node.getChildren()) {
            processTreeSequentially(child, results);
        }
    }

    public void processTreeInParallel(Node node, List<Integer> results) throws InterruptedException {
        List<Runnable> tasks = new ArrayList<>();
        if (!node.getChildren().isEmpty()) {
            for (final Node child : node.getChildren()) {
                tasks.add(() -> processTreeSequentially(child, results));
            }
            for (Runnable task : tasks) {
                executor.submit(task);
            }
            while (!tasks.isEmpty()) {
                Thread.sleep(10);
            }
        } else {
            results.add(node.compute());
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Node root = new Node(1);
        Node child1 = new Node(2);
        Node child2 = new Node(3);
        root.addChild(child1);
        root.addChild(child2);

        List<Integer> results = new ArrayList<>();

        Processor processor = new Processor(executor);
        processor.processTreeInParallel(root, results);
        System.out.println(results);

        executor.shutdown();
    }
}

